BoundaryValue read(const char* path){std::ifstream f(path);auto r=parse_boundary_json(std::string((std::istreambuf_iterator<char>(f)),{}));assert(r.ok);return std::move(r.value);}
struct FirstPhaseActivity final:ActivityRead {bool in_open_battle(const StableId&)const override{return false;}bool in_interaction(const StableId&,const StableId&)const override{return false;}};
int main(int argc,char** argv){assert(argc==4);auto unsupported=decode_estate_command("estate_build",BoundaryValue{BoundaryValue::Dict{}});assert(!unsupported.ok&&unsupported.error.kind==ErrorKind::unsupported_capability);auto raw=read(argv[1]),before=read(argv[2]),after=read(argv[3]);assert(boundary::object(*before.find("battles"),"").empty());assert(boundary::object(*before.find("interactions"),"").empty());auto common_catalog=decode_common_catalog(*raw.find("data"));assert(common_catalog.ok);auto catalog=decode_estate_catalog(*raw.find("data"),common_catalog.value);assert(catalog.ok);before.find("results")->data=BoundaryValue::Dict{};auto seed=decode_common_seed(before,common_catalog.value);auto estate=decode_estate_seed(before);assert(seed.ok&&estate.ok);auto shared=std::make_shared<const CommonCatalog>(common_catalog.value);CommonStore store(seed.value,shared);FirstPhaseActivity activity;assert(validate_estate(store,estate.value,catalog.value,*shared).ok);store.state().next_instance_id=673;auto stepped=step_estate(store,estate.value,catalog.value,*shared,activity,1);if(!stepped.ok){std::cerr<<stepped.error.original.code<<"\n";return 1;}assert(stepped.value.events==std::vector<StableId>{"estate:674"}&&store.state().next_instance_id==675);auto out=encode_estate_state(estate.value);auto diff=compare_boundary(*out.find("estates"),*after.find("estates"));assert(diff.values_equal);for(auto& fact:std::get<BoundaryValue::Dict>(out.find("facts")->data))assert(compare_boundary(fact.second,*after.find("facts")->find(fact.first)).values_equal);auto common=encode_common_state(store.state());assert(compare_boundary(*common.find("inventories")->find("inventory.estate"),*after.find("inventories")->find("inventory.estate")).values_equal);store.state().identity.tick=1;assert(validate_estate(store,estate.value,catalog.value,*shared).ok);auto replay=step_estate(store,estate.value,catalog.value,*shared,activity,1);assert(replay.ok&&!replay.value.applied);
 // 此独立命令fixture从同种子在庄园开始，明确不声称测试move_local派发。
 CommonStore commands(seed.value,shared);auto estate2=decode_estate_seed(before).value;commands.state().actions=OrderedTable<ActionCoreView>{};ActorMutation player;player.actor_id="actor.player";player.action_id="";player.location=SettlementLocation{"city.west","west.estate"};assert(commands.apply_actor(player).ok);
 auto full=preview_estate(commands,estate2,catalog.value,*shared,activity,"actor.player",EstateTransfer{"estate.riverside","item.grain",20,{ },false,false});assert(!full.ok&&full.error.original.code=="EstateStorageFull");auto quote=preview_estate(commands,estate2,catalog.value,*shared,activity,"actor.player",EstateTransfer{"estate.riverside","item.grain",10,{},false,false});assert(quote.ok);auto transferred=apply_estate(commands,estate2,catalog.value,*shared,activity,"actor.player",quote.value);assert(transferred.ok);assert(commands.count("bag:actor.player","item.grain",{{Owner::Kind::actor,"actor.player",{}}}).value==10);auto fund=preview_estate(commands,estate2,catalog.value,*shared,activity,"actor.player",EstateFund{"estate.riverside",792});assert(fund.ok);assert(apply_estate(commands,estate2,catalog.value,*shared,activity,"actor.player",fund.value).ok);assert(commands.wallet("wallet.player")->balance==8);assert(validate_estate(commands,estate2,catalog.value,*shared).ok);CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);assert(visit_estate_checkpoint(writer,estate2).ok&&writer.finish().ok);EstateState restored;const auto& input=bytes;CodecVisitor reader(input);assert(visit_estate_checkpoint(reader,restored).ok&&reader.finish().ok);assert(compare_boundary(encode_estate_state(estate2),encode_estate_state(restored)).exact());assert(validate_estate(commands,restored,catalog.value,*shared).ok);auto broken=estate2;for(auto& row:broken.facts.rows())if(auto* fact=std::get_if<EstateManagementFact>(&row.second))if(fact->transfer){fact->transfer->from_inventory_id=fact->transfer->to_inventory_id;break;}assert(!validate_estate(commands,broken,catalog.value,*shared).ok);std::cout<<"state_estate: PASS (1000-actor production/fact/asset equality, replay, storage rejection, withdraw/fund)\n";
}
